function memoryVault(key){return {async getPublicIdentity(){return {publicKey:key.encoded,fingerprint:key.fingerprint};},async signChallenge(fields,context){for(const name of ['purpose','serverId','userId','bindingRevision'])assert.equal(fields[name],context[name]);assert.equal(fields.sessionBinding,digest(context.sessionToken));return crypto.sign(null,challengeBytes(fields),key.privateKey).toString('base64url');},async signRequest(fields,context){for(const name of ['serverId','userId','deviceId','bindingRevision','leaseId'])assert.equal(fields[name],context[name]);assert.equal(fields.sessionBinding,digest(context.sessionToken));return crypto.sign(null,requestBytes(fields),key.privateKey).toString('base64url');},dispose(){}};}
function normalClient(t,f,key){const client=createTeamClient({fetchImpl:f.transport,now:()=>f.now,deviceIdentity:{vault:memoryVault(key),platform:'win32',displayName:'Synthetic administrator boundary'}});t.after(()=>client.clearSession());return client;}
function desktopBridge(t,client,dialog={}){const handlers=new Map(),frame={url:APP_URL},window={webContents:{mainFrame:frame}},dispose=registerDesktopBridge({ipcMain:{handle:(name,action)=>handlers.set(name,action),removeHandler:name=>handlers.delete(name)},window,client,dialog:{showOpenDialog:async()=>({canceled:true,filePaths:[]}),showSaveDialog:async()=>({canceled:true}),...dialog}});t.after(dispose);const event={sender:window.webContents,senderFrame:frame};return {call:(name,input,evt=event)=>handlers.get('shenyi:'+name)(evt,input),handlers,event};}
