 t.mock.method(fs,'open',async()=>{opens++;if(phase!=='file-read')throw Error('Synthetic source must remain unopened');return {stat:async()=>({isFile:()=>true,size:9}),read:async buffer=>{reads++;if(reads===1){Buffer.from('synthetic').copy(buffer);ok(await f.change({actor:owner,role:null}));return {bytesRead:9};}return {bytesRead:0};},close:async()=>{closed=true;}};});t.mock.method(fs,'writeFile',async()=>{writes++;});const bridge=desktopBridge(t,client,{showOpenDialog:async()=>{if(phase==='open-dialog')ok(await f.change({actor:owner,role:null}));return {canceled:false,filePaths:['D:/synthetic-admin-source.txt']};},showSaveDialog:async()=>{ok(await f.change({actor:owner,role:null}));return {canceled:false,filePath:'D:/synthetic-admin-never-written.bin'};}}),start=f.calls.filter(row=>row.method==='POST'&&row.path.endsWith('/submissions')).length,result=phase==='save-dialog'?await bridge.call('project-submission-download',{teamId:'team-a',projectId:'p-a',taskId:'t-a',submissionId:submission.id}):await bridge.call('upload',{teamId:'team-a',taskId:'t-a',revision:1});assert.equal(ledgerOldChannelNames(bridge.handlers).length,123);assert.equal(result.ok,false);assert.equal(writes,0);assert.equal(f.calls.filter(row=>row.method==='POST'&&row.path.endsWith('/submissions')).length,start);assert.equal(client.getDeviceStatus().state,'signed_out');if(phase==='open-dialog')assert.equal(opens,0);if(phase==='file-read'){assert.ok(reads>0);assert.equal(closed,true);}await client.login({username:'tech-a',password:PASSWORD});assert.equal(client.getDeviceStatus().state,'ready');assert.deepEqual((await client.getSession()).memberships,[]);assert.ok((await client.getBusinessRoleManagementAccess()).teams.some(row=>row.teamId==='team-a'));
